import pytest
from black.ranges import parse_line_ranges

@pytest.mark.parametrize(
    "line_ranges, expected",
    [
        (["1-1"], [(1, 1)]),
        (["1-3"], [(1, 3)]),
        (["1-1", "3-4"], [(1, 1), (3, 4)]),
    ],
)
def test_parse_line_ranges_valid(line_ranges, expected):
    assert parse_line_ranges(line_ranges) == expected

@pytest.mark.parametrize(
    "line_ranges, expected_msg",
    [
        (["5-3"], "Incorrect --line-ranges value, expect START <= END, found '5-3'"),
        (["0-5"], "Incorrect --line-ranges value, expect positive integers, found '0-5'"),
        (["-1-5"], "Incorrect --line-ranges value, expect positive integers, found '-1-5'"),
        (["5-0"], "Incorrect --line-ranges value, expect positive integers, found '5-0'"),
        (["-1--2"], "Incorrect --line-ranges value, expect positive integers, found '-1--2'"),
    ],
)
def test_parse_line_ranges_invalid(line_ranges, expected_msg):
    with pytest.raises(ValueError, match=expected_msg):
        parse_line_ranges(line_ranges)

